import React, { useState } from "react";
import { supabase } from "../supabaseClient";

const LoginForm = ({ setAdmin }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();
    const { user, session, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) setError(error.message);
    else setAdmin(true); // simple way to switch role in frontend
  };

  return (
    <form onSubmit={handleLogin} style={{ padding: "20px" }}>
      <h2>Admin Login</h2>
      {error && <p style={{ color: "red" }}>{error}</p>}
      <input type="email" placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} required />
      <input type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)} required />
      <button type="submit">Login</button>
    </form>
  );
};

export default LoginForm;
